async ({ shell: { exec } }) => {
  const b = await exec("gh pr view 83 --json body -q .body", { raise: true });
  const body = b.stdout
    .replace("with the commands from the job summary:", "with the commands that were in the job summary:")
    .replace("- The job summary keeps the commands only in `output` mode, where pi-action posts no comment. The workflow log still shows them in the `🧵 Thread` group.", "- The job summary no longer shows the commands, in any mode: each comment has them, and the workflow log shows them in the `🧵 Thread` group (also in `output` mode, where pi-action posts no comment).");
