  const e = await exec("gh pr edit 83 --body-file /tmp/body.md && gh pr merge 83 --squash --delete-branch=false 2>&1; gh pr view 83 --json state,mergeCommit -q '.state+\" \"+.mergeCommit.oid'", { timeoutMs: 60000 });
  return e;
}
